def format_bytes(n):
    """Return a human-readable byte size string, e.g. '1.5 KB'."""
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    size = n
    for unit in units:
        if size < 1024 or unit == 'TB':
            break
        size /= 1024
    if size == int(size):
        return f"{int(size)} {unit}"
    return f"{size:.1f} {unit}"
